INSERT INTO answers(id, question_id, text, correct) VALUES
 ('e8aba271-a69f-4e80-879f-940ee099aa32','c99aa30e-aaec-46f9-9ae7-b24b08e7ef16','El castellano es la lengua española oficial del Estado.',true),
 ('f2f05f7b-e794-4ec3-abb2-c35ad0354602','c99aa30e-aaec-46f9-9ae7-b24b08e7ef16','Las asociaciones que persigan fines o utilicen medios tipifi cados como delito son ilegales.',false),
 ('35540f3e-469f-4629-9104-da7ecbd61d4a','c99aa30e-aaec-46f9-9ae7-b24b08e7ef16','Ningún español de origen podrá ser privado de su nacionalidad.',false),
 ('0e1e4555-90e2-45a6-8e2a-cd2f0d91ed7c','c99aa30e-aaec-46f9-9ae7-b24b08e7ef16','CAPÍTULO PRIMERO de los españoles y los extRanjeRos',false),
 ('23b6929d-717e-44bb-9d03-ba3cafd1ae4c','b59e155a-32ba-4723-a827-39f080ebc14e','Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.',true),
 ('d154817d-e334-4312-8e5b-dfbf91f3b603','b59e155a-32ba-4723-a827-39f080ebc14e','Para la ejecución de las medidas previstas en el apartado anterior, el Gobierno podrá dar instrucciones a todas las autoridades de las Comunidades Autónomas.',false),
 ('363f3f92-642c-4cd5-aa2b-839995f3f260','b59e155a-32ba-4723-a827-39f080ebc14e','Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.',false),
 ('e8a685c7-fe05-417b-89d4-a48d0a3c2819','b59e155a-32ba-4723-a827-39f080ebc14e','En cada Cámara habrá una Diputación Permanente com puesta por un mínimo de veintiún miembros, que representarán a los grupos parlamentarios, en proporción a su importancia numérica.',false),
 ('c78965a0-0a2d-4cb9-8ba2-9da1c21e7600','37cd793b-c562-470a-a0b5-3bbdb318bf6f','En los Presupuestos Generales del Estado podrá estable cerse una asignación a las Comunidades Autónomas en función del volumen de los servicios y actividades estatales que hayan asumido y de la garantía de un nivel mínimo en la prestación de…',false),
 ('c1a55248-6c40-4443-9545-2025b2eaac63','37cd793b-c562-470a-a0b5-3bbdb318bf6f','La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social.',true),
 ('a63b9cce-20d7-4118-8346-c02708cc0225','37cd793b-c562-470a-a0b5-3bbdb318bf6f','La detención preventiva no podrá durar más del tiempo estrictamente necesario para la realización de las averigua ciones tendentes al esclarecimiento de los hechos, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá…',false),
 ('362eb450-3858-4040-8894-0ffced6996b1','37cd793b-c562-470a-a0b5-3bbdb318bf6f','Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento; si no lo hubiese nom brado, será tutor el padre o la madre mientras…',false),
 ('b6ccf6fc-4f7d-48ca-a632-0ee5d155e442','2854425e-c3ff-4724-abbb-88f0d8b928f7','La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.',false),
 ('d8b03917-65c9-497b-8d8a-7a15f679f6d8','2854425e-c3ff-4724-abbb-88f0d8b928f7','El Gobierno responde solidariamente en su gestión política ante el Congreso de los Diputados.',false),
 ('06fe3dfe-72e8-43d4-b41b-d1aafb80e09e','2854425e-c3ff-4724-abbb-88f0d8b928f7','El Congreso y el Senado, y, en su caso, ambas Cámaras conjuntamente, podrán nombrar Comisiones de investiga ción sobre cualquier asunto de interés público.',false),
 ('1808afe0-0a48-46ab-88f3-3e898de6c082','2854425e-c3ff-4724-abbb-88f0d8b928f7','La nacionalidad española se adquiere, se conserva y se pierde de acuerdo con lo establecido por la ley.',true),
 ('4572fbcd-50a3-4a4a-a4c9-f5b637acf89e','a21e8e7b-c8ed-4951-94d4-97dc7513ee0d','La Reina consorte o el consorte de la Reina no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia.',false),
 ('5dbb7e61-cd0a-4e71-bd93-77d5efe5d82a','a21e8e7b-c8ed-4951-94d4-97dc7513ee0d','Los extranjeros gozarán en España de las libertades públicas que garantiza el presente Título en los términos que esta blezcan los tratados y la ley.',true),
 ('e48733bc-e34b-4ce3-a04c-948e22c411c1','a21e8e7b-c8ed-4951-94d4-97dc7513ee0d','La ley regulará los casos en que, por razón de parentesco o de secreto profesional, no se estará obligado a declarar sobre hechos presuntamente delictivos.',false),
 ('a2177a0b-1fd8-4d24-8e83-023d24e7e247','a21e8e7b-c8ed-4951-94d4-97dc7513ee0d','b) En el supuesto de que la iniciativa del proceso autonómico no llegara a prosperar por no cumplir los requisitos previstos en el artículo 143.',false),
 ('06204aa9-7aa2-4136-ae97-317ba2db98c9','65f1ac2e-15f8-4a49-b662-980eb92e04dd','Se garantiza la libertad ideológica, religiosa y de culto de los individuos y las comunidades sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.',true),
 ('8065de49-9e38-4128-b61f-cb42ac9353c3','65f1ac2e-15f8-4a49-b662-980eb92e04dd','Las Cámaras se reunirán en sesión conjunta para ejercer las competencias no legislativas que el Título II atribuye expresamente a las Cortes Generales.',false),
